  Profile section { Loop Outer { outline |> TraceLoop } }
  return Boss { on: support; profile: section; height: 1mm }
}

Template<Spec: PickupSpec> Struct Humbucker {
  Concept Struct layout on XY {
    Point2 upperCenter { position: [0mm, Spec.coilOffset] }
    Point2 lowerCenter { position: [0mm, -Spec.coilOffset] }
    Axis2 longitudinal { origin: [0mm, 0mm]; direction: [1, 0] }
    Axis2 transverse { origin: [0mm, 0mm]; direction: [0, 1] }
    Point2 firstPole { position: [-2.5 * Spec.polePitch, Spec.coilOffset] }
    RoundedRect2 baseOutline { center: [0mm, 0mm]; size: [Spec.width, Spec.depth]; radius: 4mm }
  }
  Profile baseProfile using layout { Loop Outer { baseOutline |> TraceLoop } }
  Plane baseTop { origin: [0mm, 0mm, Spec.baseHeight]; normal: [0, 0, 1]; up: [0, 1, 0] }
  Plane coilTop { origin: [0mm, 0mm, Spec.baseHeight + Spec.coilHeight]; normal: [0, 0, 1]; up: [0, 1, 0] }
  Compose Body {
    Base housing { profile: baseProfile; from: 0mm; to: Spec.baseHeight; role: Stock }
    Feature upperCoil = Coil(center: layout.upperCenter, width: Spec.coilWidth, depth: Spec.coilDepth, height: Spec.coilHeight, support: baseTop)
    Feature lowerCoil = Coil(center: layout.lowerCenter, width: Spec.coilWidth, depth: Spec.coilDepth, height: Spec.coilHeight, support: baseTop)
    Feature poleSeed = Pole(center: layout.firstPole, support: coilTop)
    Linear Pattern poles {
      source: poleSeed
      direction: layout.longitudinal.Direction
      count: 6
      spacing: Spec.polePitch
    }
  }
  expose { Semantic Mount { DatumFrame Frame = [0mm, 0mm, 0mm] x [1, 0, 0] y [0, 1, 0] z [0, 0, 1]; } }
}

// A complete decorative pickup selector, seated at the underside of its ring.
Subassembly PickupSelector {
  <Assembly PickupSelector>
    <Part SelectorRing = Drum<R:16mm,H:1.5mm>>
      material: IvoryPolymer;
      Placement { from: BottomSeat.Frame; to: World; }
    </Part>
    <Part SelectorStem = Drum<R:2.5mm,H:12mm>>
      material: Steel;
      Placement { from: BottomSeat.Frame; to: World; translateLocal: [0mm, 0mm, 1.5mm]; }
    </Part>
    <Part SelectorTip = Drum<R:4mm,H:7mm>>
      material: IvoryPolymer;
      Placement { from: BottomSeat.Frame; to: World; translateLocal: [0mm, 0mm, 11mm]; }
    </Part>
  </Assembly>
  anchor: PickupSelector;
  expose { DatumFrame Mount = SelectorRing.BottomSeat.Frame; }
}

// One complete tuner placeholder. The button projects along local -X.
// The opposite row clocks this same component 180deg about its mounting normal.
Subassembly GuitarTuner {
  <Assembly GuitarTuner>
    <Part TunerWasher = Drum<R:7mm,H:1.5mm>>
      material: Steel;
      Placement { from: BottomSeat.Frame; to: World; }
    </Part>
    <Part TunerPost = Drum<R:4mm,H:8mm,EntryHeight:5mm>>
      material: Steel;
      Placement { from: BottomSeat.Frame; to: World; }
    </Part>
    <Part TunerButton = Panel<L:15mm,W:19mm,H:6mm,R:5mm>>
      material: IvoryPolymer;
      Placement { from: BottomSeat.Frame; to: World; translateLocal: [-22mm, 0mm, -7mm]; }
    </Part>
    // Lateral spindle joins the button to the head, below the veneer surface.
    // It belongs to the reusable tuner, so both patterned rows share this solid.
    <Part ButtonStem = Drum<R:2.5mm,H:16mm>>
      material: Steel with { appearance: PolishedNickel; };
      Placement { from: BottomSeat.Frame; to: World;
        translateLocal: [-16mm, 0mm, -4mm];
        rotateLocal: { axis: Y; angle: 90deg } }
    </Part>
  </Assembly>
  anchor: GuitarTuner;
  expose { DatumFrame Mount = TunerWasher.BottomSeat.Frame; DatumFrame StringEntry = TunerPost.StringEntry.Frame; }
}

